"use client";

import { ArrowLeft, ArrowRight, ArrowUpRight, Heart, Plus } from "lucide-react";
import { products, photo, money } from "@/data/maison-products";
import { useCommerceStore } from "@/lib/commerce-store";

type FeaturedFurnitureSectionProps = { showAll?: boolean; favoritesOnly?: boolean };

export function FeaturedFurnitureSection({ showAll = false, favoritesOnly = false }: FeaturedFurnitureSectionProps) {
  const category = useCommerceStore((state) => state.category);
  const favorites = useCommerceStore((state) => state.favorites);
  const changeCart = useCommerceStore((state) => state.changeCart);
  const toggleFavorite = useCommerceStore((state) => state.toggleFavorite);
  const setDrawer = useCommerceStore((state) => state.setDrawer);
  const selection = products.filter((product) => {
    if (favoritesOnly && !favorites.includes(product.id)) return false;
    if (showAll || favoritesOnly || category === "Tout voir") return true;
    return product.category === category;
  });

  return (
    <section className="products-section" id="selection">
      <div className="products-top"><p className="eyebrow">{favoritesOnly ? "VOS PIÈCES PRÉFÉRÉES" : showAll ? "TOUTES LES PIÈCES" : <>LA SÉLECTION MAISON <span>—</span> 2026</>}</p><div className="carousel-controls"><button aria-label="Précédent"><ArrowLeft size={17} /></button><button aria-label="Suivant"><ArrowRight size={17} /></button></div></div>
      {selection.length === 0 ? <div className="empty-catalog"><p>{favoritesOnly ? "Vous n’avez pas encore enregistré de pièce." : "Aucun produit dans cette sélection pour le moment."}</p><a className="text-link" href="/products">Explorer les collections <ArrowUpRight size={15} /></a></div> : <div className="product-grid">{selection.map((product, index) => <article className="product-card" key={product.id}>
        <div className={`product-image product-image-${index}`}><img src={photo(product.image, 1000)} alt={product.name} loading="lazy" /><span className="product-tag">{index === 0 ? "PIÈCE SIGNATURE" : "NOUVEAU"}</span><button onClick={() => toggleFavorite(product.id)} className={`favorite-button ${favorites.includes(product.id) ? "is-favorite" : ""}`} aria-label={favorites.includes(product.id) ? "Retirer des favoris" : "Ajouter aux favoris"}><Heart size={18} strokeWidth={1.5} fill={favorites.includes(product.id) ? "currentColor" : "none"} /></button><button className="quick-add" onClick={() => { changeCart(product.id, 1); setDrawer("cart"); }}><Plus size={17} /> Ajouter au panier</button></div>
        <div className="product-info"><div><h3>{product.name}</h3><p>{product.detail}</p></div><strong>{money(product.price)}</strong></div>
      </article>)}</div>}
      {!showAll && !favoritesOnly && <a className="mobile-link text-link" href="/products">Toute la collection <ArrowUpRight size={15} /></a>}
    </section>
  );
}
